// Self-hosted, base64-embedded Sinhala/Tamil webfonts (script-specific
// subset only, weight 400 - Latin characters in the same text fall
// through to the font stack next generic keyword, same as every other
// FONT_PRESETS entry).
// Embedded as raw base64 rather than a remote @font-face URL for the same
// reason lib/iconAssets.ts embeds icon markup instead of importing
// lucide-static at request time: the print-proof renderer runs headless
// Chromium under @sparticuz/chromium in a Netlify Function, and this app
// already got burned once by an unbudgeted network round-trip in that
// render path (see lib/renderOrderPdf.ts timeout history) - self-hosting
// keeps rendering these fonts a pure CPU/memory cost, never a network one,
// and identical between the live editor, free preview, and final PDF.
// Source: Google Fonts (Noto Sans Sinhala v36, Noto Sans Tamil v31,
// Yaldevi v17), each font the sinhala/tamil-subset @font-face src from
// fonts.googleapis.com/css2, extracted 2026-08-24.

export const NOTO_SANS_SINHALA_WOFF2 = "";
export const NOTO_SANS_TAMIL_WOFF2 = "";
export const YALDEVI_WOFF2 = "";
